-- wave205 (04/10/26): the Strategy app rebuilt; the organizational goals edited live, Google-Doc style.
-- Steel (04/10/26): "organizational goals, and departments own projects"; department goals retired as a tier (kept, archived);
-- click-to-edit with autosave, who is editing live, comments on goals and milestones, version history with Restore;
-- "each goal's owners and admins edit; all staff read and comment; board viewers read-only", enforced here.
-- Data: wa205_strategy_data.sql (generated by wa205_seed.py from the approved draft).

-- ---------- goals: the org tier's new fields, and retiring without losing anything ----------
alter table public.goals
  add column if not exists number smallint,
  add column if not exists baseline text,
  add column if not exists target_fy29 text,
  add column if not exists target_fy31 text,
  add column if not exists approval text,
  add column if not exists approved_at timestamptz,
  add column if not exists approved_by text,
  add column if not exists retired_at timestamptz,
  add column if not exists retired_by text,
  add column if not exists retired_note text,
  add column if not exists status_before_retire text,
  add column if not exists maps_to_goal_id bigint references public.goals(id),
  add column if not exists superseded_by bigint references public.goals(id),
  add column if not exists moved_to_project_id bigint references public.projects(id);
alter table public.goals add constraint goals_approval_check check (approval is null or approval in ('draft', 'approved'));
alter table public.goals add constraint goals_number_check check (number is null or (number between 1 and 20 and department = 'org'));
create index if not exists goals_maps_to_goal_id_idx on public.goals(maps_to_goal_id);
create index if not exists goals_superseded_by_idx on public.goals(superseded_by);
create index if not exists goals_moved_to_project_id_idx on public.goals(moved_to_project_id);
comment on column public.goals.detail is 'The goal statement. For an organizational goal (wave205) the SMART statement as the board reads it; for the older department goals, Specific. Edited through strategy_save().';
comment on column public.goals.measure is 'How the goal is measured. For an organizational goal (wave205) its headline measure (one Hub measure per goal), e.g. Meals served a year.';
comment on column public.goals.why is 'Why this goal matters (Relevant). Organizational goals: the Why from the approved plan.';
comment on column public.goals.number is 'wave205: the order an organizational goal is presented in (1 to 5 in the FY27 to FY31 plan); null for department goals and retired org goals before wave205.';
comment on column public.goals.baseline is 'wave205: the measured starting point of the headline measure, as text (2,269 (2025), Not tracked).';
comment on column public.goals.target_fy29 is 'wave205: the 3-year target (FY29, Sep 30, 2029) of the headline measure, as text.';
comment on column public.goals.target_fy31 is 'wave205: the 5-year target (FY31), gated by the FY29 gate, as text.';
comment on column public.goals.approval is 'wave205: draft (shown as Draft for board approval) or approved; set for all active org goals at once by an admin through strategy_set_approval(). Null for department goals.';
comment on column public.goals.approved_at is 'wave205: when an admin marked the org goals approved by the board.';
comment on column public.goals.approved_by is 'wave205: the email of the admin who marked them approved.';
comment on column public.goals.retired_at is 'wave205: when the goal was retired (archived, never removed). Retired goals keep their wins, comments and history; the Hub hides them from every default view and shows them under Strategy > Goals > Retired goals. status is archived while retired.';
comment on column public.goals.retired_by is 'wave205: who retired the goal (an email, or wave205 migration).';
comment on column public.goals.retired_note is 'wave205: why it was retired, in words (superseded by, or the tier retired).';
comment on column public.goals.status_before_retire is 'wave205: the status the goal had when it was retired (status becomes archived).';
comment on column public.goals.maps_to_goal_id is 'wave205: for a retired goal, the active organizational goal it served (null when no obvious fit). Make it a project uses it as the new project''s goal.';
comment on column public.goals.superseded_by is 'wave205: for a retired org goal, the organizational goal that replaced it (null when retired outright).';
comment on column public.goals.moved_to_project_id is 'wave205: set once when a retired department goal was turned into a project (strategy_retired_to_project); the button then shows the project instead.';

-- ---------- projects can serve one milestone of their goal ----------
-- (goal_milestones is created below; the column is added after it)

-- ---------- the owners, as roster rows ----------
create table public.goal_owners (
  id bigint generated always as identity primary key,
  goal_id bigint not null references public.goals(id),
  member_id bigint not null references public.team_members(id),
  is_lead boolean not null default false,
  focus text,
  sort integer not null default 0,
  added_at timestamptz not null default now(),
  added_by text,
  removed_at timestamptz,
  unique (goal_id, member_id)
);
create index goal_owners_goal_id_idx on public.goal_owners(goal_id);
create index goal_owners_member_id_idx on public.goal_owners(member_id);
comment on table public.goal_owners is 'wave205: who owns each organizational goal, as roster rows (team_members). An active row (removed_at null) lets that person edit the goal (wa205_can_edit). One lead per goal (is_lead). Written only through strategy_owner_set() (the goal''s owners and admins); read by staff and board viewers.';
comment on column public.goal_owners.focus is 'What this owner carries for the goal, in words (Toronto; Grants and finance), or null.';
comment on column public.goal_owners.removed_at is 'Set when the owner was taken off the goal (rows are kept for the history; Restore brings one back).';

-- ---------- the yearly milestones ----------
create table public.goal_milestones (
  id bigint generated always as identity primary key,
  goal_id bigint not null references public.goals(id),
  fy text not null check (fy in ('FY27', 'FY28', 'FY29', 'FY30', 'FY31')),
  sort integer not null default 0,
  body text not null default '',
  status text not null default 'not started' check (status in ('not started', 'in progress', 'done', 'at risk', 'carried forward')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by text,
  archived_at timestamptz
);
create index goal_milestones_goal_id_idx on public.goal_milestones(goal_id, fy, sort);
comment on table public.goal_milestones is 'wave205: an organizational goal''s milestones, one row per item of a fiscal year (FY27, FY28, FY29, FY31; FY30 allowed), each with its status. Projects can serve one (projects.milestone_id). Written only through strategy_save(), strategy_add() and strategy_remove() by the goal''s owners and admins; read by staff and board viewers. Archived, never removed.';
comment on column public.goal_milestones.fy is 'The fiscal year (Oct 1 to Sep 30) the milestone belongs to: FY27 is Oct 2026 to Sep 2027.';
comment on column public.goal_milestones.status is 'not started, in progress, done, at risk, or carried forward (FY29 targets carry forward when the FY29 gate is not met).';
comment on column public.goal_milestones.updated_by is 'The email of the last person who changed it (the page shows their name in the live notice).';
comment on column public.goal_milestones.archived_at is 'Set when it was removed from the goal (Restore in the history brings it back).';

alter table public.projects add column if not exists milestone_id bigint references public.goal_milestones(id);
create index if not exists projects_milestone_id_idx on public.projects(milestone_id);
comment on column public.projects.milestone_id is 'wave205: the milestone of its goal (goal_id) this project serves, or null. Set with goal_id through strategy_link_project().';
comment on column public.projects.goal_id is 'The organizational goal this project serves (since wave205 departments own projects and link them straight to an org goal; department goals are retired). Set through strategy_link_project() or the project editors.';

-- ---------- the paths ----------
create table public.goal_paths (
  id bigint generated always as identity primary key,
  goal_id bigint not null references public.goals(id),
  sort integer not null default 0,
  body text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by text,
  archived_at timestamptz
);
create index goal_paths_goal_id_idx on public.goal_paths(goal_id, sort);
comment on table public.goal_paths is 'wave205: the paths of an organizational goal (how we get there), one row each. Written only through strategy_save(), strategy_add() and strategy_remove() by the goal''s owners and admins; read by staff and board viewers. Archived, never removed.';
comment on column public.goal_paths.updated_by is 'The email of the last person who changed it.';
comment on column public.goal_paths.archived_at is 'Set when it was removed from the goal (Restore brings it back).';

-- ---------- every change, for the history and Restore ----------
create table public.goal_history (
  id bigint generated always as identity primary key,
  goal_id bigint not null references public.goals(id),
  entity text not null check (entity in ('goal', 'milestone', 'path', 'owner', 'project')),
  entity_id bigint not null,
  field text not null,
  old_value text,
  new_value text,
  old_ref bigint,
  new_ref bigint,
  changed_by text,
  changed_by_name text,
  changed_at timestamptz not null default now(),
  restored_from bigint references public.goal_history(id)
);
create index goal_history_goal_id_idx on public.goal_history(goal_id, changed_at desc);
create index goal_history_entity_idx on public.goal_history(entity, entity_id, field);
create index goal_history_restored_from_idx on public.goal_history(restored_from);
comment on table public.goal_history is 'wave205: every change to an organizational goal, its milestones, paths, owners and the projects linked to it (who, when, the field, the old and new value), written by the trigger wa205_hist() only. Read by staff and board viewers (Strategy > Goals > History); Restore goes through strategy_restore().';
comment on column public.goal_history.entity is 'goal, milestone, path, owner or project (entity_id is that row''s id).';
comment on column public.goal_history.field is 'The column that changed (title, detail, why, measure, baseline, target_fy29, target_fy31, status, due_date, approval, retired_at, body, fy, archived_at, goal_id, milestone_id, is_lead, focus), or added (a new milestone, path or owner) and removed (an owner taken off).';
comment on column public.goal_history.old_ref is 'For project links (goal_id, milestone_id): the id it pointed at before; Restore puts it back.';
comment on column public.goal_history.new_ref is 'For project links: the id it points at after the change.';
comment on column public.goal_history.changed_by is 'The email of the person (wa_email()), or wave205 migration for the seed.';
comment on column public.goal_history.changed_by_name is 'Their roster name when known, else the email.';
comment on column public.goal_history.restored_from is 'When this change was a Restore: the history row it restored.';

-- ---------- the plan around the goals (mission, the roadmap, the gate) ----------
create table public.strategy_plan (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by text
);
comment on table public.strategy_plan is 'wave205: the plan around the organizational goals, from the approved draft: mission, mission_note, window, why_reset, long_range, approval (the board meeting and its label), rule, roadmap (phases, the checkpoint, the FY29 gate and its rule), cadence, source. Read by staff and board viewers on Strategy > Goals; written by migrations only.';

-- ---------- the Strategy Library: documents pinned for everyone ----------
create table public.strategy_docs (
  id bigint generated always as identity primary key,
  title text not null,
  url text check (url is null or url ~ '^https://'),
  group_label text not null default 'Our plans',
  doc_date text,
  direction text,
  status_note text,
  goals smallint[] not null default '{}',
  pinned boolean not null default true,
  sort integer not null default 0,
  added_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  archived_at timestamptz
);
create index strategy_docs_pinned_idx on public.strategy_docs(pinned, sort);
comment on table public.strategy_docs is 'wave205: the Strategy Library, the direction-setting documents (our plans, consulting work, sources) with their links, what each sets and where it stands. pinned is the Hub''s important-document flag: pinned documents lead the Library and the Goals page. Admins add, edit and pin through strategy_doc_save() and strategy_doc_pin(); staff and board viewers read. Archived, never removed.';
comment on column public.strategy_docs.group_label is 'The Library''s shelf: Our plans, Consulting work, Sources (or another an admin types).';
comment on column public.strategy_docs.doc_date is 'When the document was written, as the plan states it (Oct 2025, Jun to Aug 2026).';
comment on column public.strategy_docs.direction is 'The direction the document sets.';
comment on column public.strategy_docs.status_note is 'Where it stands (Oct 2026), or which goals it feeds.';
comment on column public.strategy_docs.goals is 'The goal numbers (goals.number) the document feeds, when the plan says so.';
comment on column public.strategy_docs.pinned is 'The important-document flag: pinned documents show first in the Library and on the Goals page. Admins pin and unpin.';

-- ---------- comments on goals and milestones, threaded ----------
alter table public.goal_comments
  add column if not exists parent_id bigint references public.goal_comments(id),
  add column if not exists milestone_id bigint references public.goal_milestones(id),
  add column if not exists author_email text,
  add column if not exists edited_at timestamptz;
create index if not exists goal_comments_goal_id_idx2 on public.goal_comments(goal_id, created_at);
create index if not exists goal_comments_parent_id_idx on public.goal_comments(parent_id);
create index if not exists goal_comments_milestone_id_idx on public.goal_comments(milestone_id);
comment on column public.goal_comments.parent_id is 'wave205: the comment this one answers (a thread), or null for a new thread.';
comment on column public.goal_comments.milestone_id is 'wave205: the milestone the thread is about, or null for the goal itself.';
comment on column public.goal_comments.author_email is 'wave205: the author''s email (comments from wave205 on); the author edits their own (or an admin). Older rows have only author (a name).';
comment on column public.goal_comments.edited_at is 'wave205: when the author last edited it.';

-- ---------- who may do what ----------
create or replace function public.wa205_is_owner(p_goal bigint) returns boolean
language sql stable security definer set search_path to '' as $$
  select public.wa_email() <> '' and exists (
    select 1 from public.goal_owners o join public.team_members m on m.id = o.member_id
    where o.goal_id = p_goal and o.removed_at is null and lower(m.email) = public.wa_email());
$$;
comment on function public.wa205_is_owner(bigint) is 'wave205: true when the signed-in person is an active owner of that goal (goal_owners, matched by their roster email). Access: authenticated.';

create or replace function public.wa205_can_edit(p_goal bigint) returns boolean
language sql stable security definer set search_path to '' as $$
  select public.is_wa_staff() and (public.is_hub_admin() or public.wa205_is_owner(p_goal));
$$;
comment on function public.wa205_can_edit(bigint) is 'wave205: who edits an organizational goal (its fields, milestones, paths, owners): the goal''s owners and the Hub admins. Checked inside every strategy_* writer. Access: authenticated.';

create or replace function public.wa205_can_comment() returns boolean
language sql stable security definer set search_path to '' as $$
  select public.is_wa_staff() and not exists (select 1 from public.hub_roles r where r.email = public.wa_email() and r.role in ('viewer', 'blocked'));
$$;
comment on function public.wa205_can_comment() is 'wave205: staff who may comment on goals and link projects to them: every staff account except viewers (the board view) and blocked people. Board viewers read only. Access: authenticated.';

create or replace function public.wa205_goal_writable(p_id bigint, p_dept text, p_retired timestamptz) returns boolean
language sql stable security definer set search_path to '' as $$
  select public.is_hub_admin() or (p_retired is null and p_dept is distinct from 'org' and public.wa205_can_comment()) or (p_retired is null and p_dept = 'org' and public.wa205_is_owner(p_id));
$$;
comment on function public.wa205_goal_writable(bigint, text, timestamptz) is 'wave205: the row rule for direct writes to goals: admins always; an organizational goal only by its owners; a retired goal only by admins; anything else by staff who may comment. Used by the restrictive policy goals_wa205_write. Access: authenticated.';

create or replace function public.wa205_who() returns text
language sql stable security definer set search_path to '' as $$
  select coalesce(nullif(current_setting('wa205.actor', true), ''), nullif(public.wa_email(), ''), 'system');
$$;
comment on function public.wa205_who() is 'wave205: who a change is by, for the history: wa205.actor when a migration sets it, else the signed-in email. Access: none (used by the trigger).';

create or replace function public.wa205_name(p_email text) returns text
language sql stable security definer set search_path to '' as $$
  select coalesce((select m.name from public.team_members m where lower(m.email) = lower(p_email) order by m.active is not false desc, m.id limit 1), p_email);
$$;
comment on function public.wa205_name(text) is 'wave205: a roster name for an email (or the email when nobody matches). Access: none (used by the trigger and the writers).';

-- ---------- the history trigger ----------
create or replace function public.wa205_hist() returns trigger
language plpgsql security definer set search_path to '' as $$
declare
  v_ent text := tg_argv[0];
  v_fields text[] := string_to_array(tg_argv[1], ',');
  o jsonb; n jsonb; f text; v_goal bigint; v_who text; v_name text; v_rest bigint; v_title text;
begin
  if coalesce(current_setting('wa205.seed', true), '') = '1' then return null; end if;
  v_who := public.wa205_who(); v_name := public.wa205_name(v_who);
  v_rest := nullif(current_setting('wa205.restored_from', true), '')::bigint;
  if tg_op = 'INSERT' then n := to_jsonb(new); o := '{}'::jsonb; else n := to_jsonb(new); o := to_jsonb(old); end if;
  if v_ent = 'goal' then
    if coalesce(n->>'department', '') <> 'org' and coalesce(o->>'department', '') <> 'org' then return null; end if;
    v_goal := (n->>'id')::bigint;
  elsif v_ent = 'project' then
    if tg_op <> 'UPDATE' then return null; end if;
    v_title := n->>'name';
    if (o->>'goal_id') is distinct from (n->>'goal_id') then
      if (o->>'goal_id') is not null and exists (select 1 from public.goals g where g.id = (o->>'goal_id')::bigint and g.department = 'org') then
        insert into public.goal_history (goal_id, entity, entity_id, field, old_value, new_value, old_ref, new_ref, changed_by, changed_by_name, restored_from)
        values ((o->>'goal_id')::bigint, 'project', (n->>'id')::bigint, 'goal_id', v_title, null, (o->>'goal_id')::bigint, (n->>'goal_id')::bigint, v_who, v_name, v_rest);
      end if;
      if (n->>'goal_id') is not null and exists (select 1 from public.goals g where g.id = (n->>'goal_id')::bigint and g.department = 'org') then
        insert into public.goal_history (goal_id, entity, entity_id, field, old_value, new_value, old_ref, new_ref, changed_by, changed_by_name, restored_from)
        values ((n->>'goal_id')::bigint, 'project', (n->>'id')::bigint, 'goal_id', null, v_title, (o->>'goal_id')::bigint, (n->>'goal_id')::bigint, v_who, v_name, v_rest);
      end if;
    end if;
    if (o->>'milestone_id') is distinct from (n->>'milestone_id') and (n->>'goal_id') is not null and exists (select 1 from public.goals g where g.id = (n->>'goal_id')::bigint and g.department = 'org') then
      insert into public.goal_history (goal_id, entity, entity_id, field, old_value, new_value, old_ref, new_ref, changed_by, changed_by_name, restored_from)
      values ((n->>'goal_id')::bigint, 'project', (n->>'id')::bigint, 'milestone_id',
        (select m.fy || ': ' || m.body from public.goal_milestones m where m.id = (o->>'milestone_id')::bigint),
        (select m.fy || ': ' || m.body from public.goal_milestones m where m.id = (n->>'milestone_id')::bigint),
        (o->>'milestone_id')::bigint, (n->>'milestone_id')::bigint, v_who, v_name, v_rest);
    end if;
    return null;
  else
    v_goal := (n->>'goal_id')::bigint;
  end if;
  if tg_op = 'INSERT' then
    insert into public.goal_history (goal_id, entity, entity_id, field, old_value, new_value, changed_by, changed_by_name, restored_from)
    values (v_goal, v_ent, (n->>'id')::bigint, 'added', null,
      case when v_ent = 'owner' then (select m.name from public.team_members m where m.id = (n->>'member_id')::bigint)
           when v_ent = 'milestone' then (n->>'fy') || ': ' || (n->>'body') else n->>'body' end,
      v_who, v_name, v_rest);
    return null;
  end if;
  foreach f in array v_fields loop
    if (o->f) is distinct from (n->f) then
      insert into public.goal_history (goal_id, entity, entity_id, field, old_value, new_value, changed_by, changed_by_name, restored_from)
      values (v_goal, v_ent, (n->>'id')::bigint,
        case when v_ent = 'owner' and f = 'removed_at' then case when (n->>'removed_at') is null then 'added' else 'removed' end else f end,
        case when v_ent = 'owner' and f = 'removed_at' then (select m.name from public.team_members m where m.id = (n->>'member_id')::bigint) else o->>f end,
        case when v_ent = 'owner' and f = 'removed_at' then (select m.name from public.team_members m where m.id = (n->>'member_id')::bigint) else n->>f end,
        v_who, v_name, v_rest);
    end if;
  end loop;
  return null;
end $$;
comment on function public.wa205_hist() is 'wave205: writes goal_history for every change to an organizational goal (goals), its milestones, paths and owners, and to a project''s goal or milestone link. Arguments: the entity and the fields to compare. Skipped while wa205.seed is 1 (the seed). Access: trigger only.';

create trigger goals_wa205_hist after update on public.goals for each row
  execute function public.wa205_hist('goal', 'title,detail,why,measure,baseline,target_fy29,target_fy31,status,due_date,progress,approval,retired_at');
create trigger goal_milestones_wa205_hist after insert or update on public.goal_milestones for each row
  execute function public.wa205_hist('milestone', 'body,status,fy,archived_at');
create trigger goal_paths_wa205_hist after insert or update on public.goal_paths for each row
  execute function public.wa205_hist('path', 'body,archived_at');
create trigger goal_owners_wa205_hist after insert or update on public.goal_owners for each row
  execute function public.wa205_hist('owner', 'is_lead,focus,removed_at');
create trigger projects_wa205_hist after update of goal_id, milestone_id on public.projects for each row
  execute function public.wa205_hist('project', '');

-- ---------- the writers (checked functions: the check is inside) ----------
create or replace function public.strategy_save(p_entity text, p_id bigint, p_field text, p_value text, p_old text)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_goal bigint; v_cur text; v_who text := public.wa_email(); h record; v_val text := p_value;
begin
  if not public.is_wa_staff() then raise exception 'Sign in with a Welfare Avenue account.'; end if;
  if p_entity = 'goal' then
    if p_field not in ('title', 'detail', 'why', 'measure', 'baseline', 'target_fy29', 'target_fy31', 'status', 'due_date') then raise exception 'That field cannot be changed here (%).', p_field; end if;
    select g.id into v_goal from public.goals g where g.id = p_id and g.department = 'org' and g.retired_at is null;
    if v_goal is null then raise exception 'That goal is not an active organizational goal.'; end if;
    execute format('select (%I)::text from public.goals where id = $1', p_field) into v_cur using p_id;
  elsif p_entity = 'milestone' then
    if p_field not in ('body', 'status', 'fy') then raise exception 'That field cannot be changed here (%).', p_field; end if;
    select m.goal_id into v_goal from public.goal_milestones m where m.id = p_id and m.archived_at is null;
    if v_goal is null then raise exception 'That milestone is not there any more.'; end if;
    execute format('select (%I)::text from public.goal_milestones where id = $1', p_field) into v_cur using p_id;
  elsif p_entity = 'path' then
    if p_field <> 'body' then raise exception 'That field cannot be changed here (%).', p_field; end if;
    select p.goal_id into v_goal from public.goal_paths p where p.id = p_id and p.archived_at is null;
    if v_goal is null then raise exception 'That path is not there any more.'; end if;
    select p.body into v_cur from public.goal_paths p where p.id = p_id;
  else
    raise exception 'Unknown kind of item (%).', p_entity;
  end if;
  if not public.wa205_can_edit(v_goal) then raise exception 'Only this goal''s owners and the admins can change it.'; end if;
  -- the per-field check: someone else saved this field since the page read it
  if coalesce(v_cur, '') <> coalesce(p_old, '') then
    select x.changed_by, x.changed_by_name, x.changed_at into h from public.goal_history x
      where x.entity = p_entity and x.entity_id = p_id and x.field = p_field order by x.id desc limit 1;
    return jsonb_build_object('ok', false, 'conflict', true, 'current', v_cur, 'by', h.changed_by_name, 'by_email', h.changed_by, 'at', h.changed_at);
  end if;
  if coalesce(v_cur, '') = coalesce(v_val, '') then return jsonb_build_object('ok', true, 'value', v_cur, 'same', true); end if;
  v_val := left(coalesce(v_val, ''), 4000);
  if p_entity = 'goal' then
    if p_field = 'title' and btrim(v_val) = '' then raise exception 'A goal needs a title.'; end if;
    if p_field = 'status' and v_val not in ('not started', 'in progress', 'on track', 'at risk', 'delayed', 'done') then raise exception 'Pick a status from the list.'; end if;
    if p_field = 'due_date' then
      if v_val !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Use a date like 2029-09-30.'; end if;
      update public.goals set due_date = v_val::date, updated_at = now(), updated_by = v_who where id = p_id;
    else
      execute format('update public.goals set %I = $1, updated_at = now(), updated_by = $2 where id = $3', p_field) using nullif(v_val, ''), v_who, p_id;
    end if;
  elsif p_entity = 'milestone' then
    if p_field = 'status' and v_val not in ('not started', 'in progress', 'done', 'at risk', 'carried forward') then raise exception 'Pick a status from the list.'; end if;
    if p_field = 'fy' and v_val not in ('FY27', 'FY28', 'FY29', 'FY30', 'FY31') then raise exception 'Pick a fiscal year from FY27 to FY31.'; end if;
    execute format('update public.goal_milestones set %I = $1, updated_at = now(), updated_by = $2 where id = $3', p_field) using v_val, v_who, p_id;
  else
    update public.goal_paths set body = v_val, updated_at = now(), updated_by = v_who where id = p_id;
  end if;
  return jsonb_build_object('ok', true, 'value', v_val, 'at', now());
end $$;
comment on function public.strategy_save(text, bigint, text, text, text) is 'wave205: autosave of one field of an organizational goal (title, detail = SMART, why, measure, baseline, target_fy29, target_fy31, status, due_date), a milestone (body, status, fy) or a path (body). p_old is the value the page started from: when the stored value differs, nothing is saved and the answer is {conflict, current, by, at} so the page can show "Ian just changed this" without losing anyone''s words. Checks inside: staff, the goal''s owners or an admin, the field list. Access: authenticated.';

create or replace function public.strategy_add(p_entity text, p_goal bigint, p_fy text, p_body text)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_id bigint; v_sort int;
begin
  if not exists (select 1 from public.goals g where g.id = p_goal and g.department = 'org' and g.retired_at is null) then raise exception 'That goal is not an active organizational goal.'; end if;
  if not public.wa205_can_edit(p_goal) then raise exception 'Only this goal''s owners and the admins can change it.'; end if;
  if p_entity = 'milestone' then
    if p_fy not in ('FY27', 'FY28', 'FY29', 'FY30', 'FY31') then raise exception 'Pick a fiscal year from FY27 to FY31.'; end if;
    select coalesce(max(sort), 0) + 1 into v_sort from public.goal_milestones where goal_id = p_goal and fy = p_fy;
    insert into public.goal_milestones (goal_id, fy, sort, body, updated_by) values (p_goal, p_fy, v_sort, left(coalesce(p_body, ''), 4000), public.wa_email()) returning id into v_id;
    return (select to_jsonb(m) from public.goal_milestones m where m.id = v_id);
  elsif p_entity = 'path' then
    select coalesce(max(sort), 0) + 1 into v_sort from public.goal_paths where goal_id = p_goal;
    insert into public.goal_paths (goal_id, sort, body, updated_by) values (p_goal, v_sort, left(coalesce(p_body, ''), 4000), public.wa_email()) returning id into v_id;
    return (select to_jsonb(p) from public.goal_paths p where p.id = v_id);
  end if;
  raise exception 'Unknown kind of item (%).', p_entity;
end $$;
comment on function public.strategy_add(text, bigint, text, text) is 'wave205: adds a milestone (with its fiscal year) or a path to an organizational goal, at the end. Checks inside: the goal''s owners or an admin. Returns the new row. Access: authenticated.';

create or replace function public.strategy_remove(p_entity text, p_id bigint)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_goal bigint;
begin
  if p_entity = 'milestone' then select goal_id into v_goal from public.goal_milestones where id = p_id and archived_at is null;
  elsif p_entity = 'path' then select goal_id into v_goal from public.goal_paths where id = p_id and archived_at is null;
  else raise exception 'Unknown kind of item (%).', p_entity; end if;
  if v_goal is null then raise exception 'That item is not there any more.'; end if;
  if not public.wa205_can_edit(v_goal) then raise exception 'Only this goal''s owners and the admins can change it.'; end if;
  if p_entity = 'milestone' then
    update public.goal_milestones set archived_at = now(), updated_at = now(), updated_by = public.wa_email() where id = p_id;
    update public.projects set milestone_id = null, updated_at = now() where milestone_id = p_id;
  else
    update public.goal_paths set archived_at = now(), updated_at = now(), updated_by = public.wa_email() where id = p_id;
  end if;
  return jsonb_build_object('ok', true);
end $$;
comment on function public.strategy_remove(text, bigint) is 'wave205: takes a milestone or a path off its goal (archived_at; kept for the history, Restore brings it back). A removed milestone''s projects stay linked to the goal. Checks inside: the goal''s owners or an admin. Access: authenticated.';

create or replace function public.strategy_owner_set(p_goal bigint, p_member bigint, p_on boolean, p_lead boolean default null, p_focus text default null)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_sort int;
begin
  if not exists (select 1 from public.goals g where g.id = p_goal and g.department = 'org' and g.retired_at is null) then raise exception 'That goal is not an active organizational goal.'; end if;
  if not public.wa205_can_edit(p_goal) then raise exception 'Only this goal''s owners and the admins can change who owns it.'; end if;
  if not exists (select 1 from public.team_members m where m.id = p_member and m.active is not false) then raise exception 'Pick someone on the roster.'; end if;
  if p_on then
    select coalesce(max(sort), 0) + 1 into v_sort from public.goal_owners where goal_id = p_goal;
    insert into public.goal_owners (goal_id, member_id, is_lead, focus, sort, added_by) values (p_goal, p_member, coalesce(p_lead, false), nullif(btrim(coalesce(p_focus, '')), ''), v_sort, public.wa_email())
      on conflict (goal_id, member_id) do update set removed_at = null,
        is_lead = coalesce(p_lead, public.goal_owners.is_lead),
        focus = case when p_focus is null then public.goal_owners.focus else nullif(btrim(p_focus), '') end;
    if p_lead then update public.goal_owners set is_lead = false where goal_id = p_goal and member_id <> p_member and is_lead; end if;
  else
    update public.goal_owners set removed_at = now(), is_lead = false where goal_id = p_goal and member_id = p_member and removed_at is null;
  end if;
  update public.goals g set owner = (select string_agg(m.name || case when o.is_lead then ' (lead)' else '' end, ', ' order by o.is_lead desc, o.sort)
      from public.goal_owners o join public.team_members m on m.id = o.member_id where o.goal_id = p_goal and o.removed_at is null),
    updated_at = now(), updated_by = public.wa_email() where g.id = p_goal;
  return jsonb_build_object('ok', true);
end $$;
comment on function public.strategy_owner_set(bigint, bigint, boolean, boolean, text) is 'wave205: adds an owner to an organizational goal (p_on true; p_lead makes them the one lead; p_focus says what they carry) or takes one off (p_on false; the row is kept with removed_at). Keeps goals.owner (text, for older views) in step. Checks inside: the goal''s owners or an admin. Access: authenticated.';

create or replace function public.strategy_link_project(p_project bigint, p_goal bigint, p_milestone bigint default null)
returns jsonb language plpgsql security definer set search_path to '' as $$
begin
  if not public.wa205_can_comment() then raise exception 'Board viewers read the goals; staff link projects.'; end if;
  if not exists (select 1 from public.projects p where p.id = p_project and p.banked_at is null) then raise exception 'That project is not there.'; end if;
  if p_goal is not null and not exists (select 1 from public.goals g where g.id = p_goal and g.department = 'org' and g.retired_at is null) then raise exception 'Link projects to one of the active organizational goals.'; end if;
  if p_milestone is not null and not exists (select 1 from public.goal_milestones m where m.id = p_milestone and m.goal_id = p_goal and m.archived_at is null) then raise exception 'That milestone belongs to another goal.'; end if;
  update public.projects set goal_id = p_goal, milestone_id = case when p_goal is null then null else p_milestone end, updated_at = now() where id = p_project;
  return jsonb_build_object('ok', true);
end $$;
comment on function public.strategy_link_project(bigint, bigint, bigint) is 'wave205: links a department''s project to an organizational goal and, optionally, one of its milestones (p_goal null unlinks). Departments own projects, so any staff account that may comment links them; board viewers cannot. Recorded in goal_history by the trigger. Access: authenticated.';

create or replace function public.strategy_comment_add(p_goal bigint, p_milestone bigint, p_parent bigint, p_body text)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_id bigint; v_body text := btrim(coalesce(p_body, ''));
begin
  if not public.wa205_can_comment() then raise exception 'Board viewers read the goals; staff comment on them.'; end if;
  if v_body = '' then raise exception 'Write something first.'; end if;
  if length(v_body) > 4000 then raise exception 'Keep a comment under 4,000 characters.'; end if;
  if not exists (select 1 from public.goals g where g.id = p_goal and g.department = 'org') then raise exception 'Comment on one of the organizational goals.'; end if;
  if p_milestone is not null and not exists (select 1 from public.goal_milestones m where m.id = p_milestone and m.goal_id = p_goal) then raise exception 'That milestone belongs to another goal.'; end if;
  if p_parent is not null and not exists (select 1 from public.goal_comments c where c.id = p_parent and c.goal_id = p_goal) then raise exception 'That thread belongs to another goal.'; end if;
  insert into public.goal_comments (goal_id, body, author, author_email, parent_id, milestone_id, created_at, updated_at)
  values (p_goal, v_body, public.wa205_name(public.wa_email()), public.wa_email(), p_parent,
    coalesce(p_milestone, (select c.milestone_id from public.goal_comments c where c.id = p_parent)), now(), now())
  returning id into v_id;
  return (select to_jsonb(c) from public.goal_comments c where c.id = v_id);
end $$;
comment on function public.strategy_comment_add(bigint, bigint, bigint, text) is 'wave205: a comment on an organizational goal or one of its milestones, or an answer in a thread (p_parent; it takes the thread''s milestone). @mentions go through the existing flow (the goal_comments_mentions trigger files hub_mentions, which wave138''s notify sends as a Slack DM, as Steel set up on 26/09/26). Checks inside: staff who may comment (not viewers). Access: authenticated.';

create or replace function public.strategy_comment_edit(p_id bigint, p_body text)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_body text := btrim(coalesce(p_body, ''));
begin
  if not exists (select 1 from public.goal_comments c where c.id = p_id and (c.author_email = public.wa_email() or public.is_hub_admin())) then raise exception 'Only the author (or an admin) edits a comment.'; end if;
  if v_body = '' then raise exception 'Write something first.'; end if;
  update public.goal_comments set body = left(v_body, 4000), edited_at = now(), updated_at = now() where id = p_id;
  return (select to_jsonb(c) from public.goal_comments c where c.id = p_id);
end $$;
comment on function public.strategy_comment_edit(bigint, text) is 'wave205: the author (or an admin) edits their goal comment. Access: authenticated.';

create or replace function public.strategy_set_approval(p_status text)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare n int;
begin
  if not public.is_hub_admin() then raise exception 'Only an admin marks the goals approved.'; end if;
  if p_status not in ('draft', 'approved') then raise exception 'draft or approved'; end if;
  update public.goals set approval = p_status,
      approved_at = case when p_status = 'approved' then now() else null end,
      approved_by = case when p_status = 'approved' then public.wa_email() else null end,
      updated_at = now(), updated_by = public.wa_email()
    where department = 'org' and retired_at is null and number is not null;
  get diagnostics n = row_count;
  insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
    values ('strategy', 'org_goals', 'approval', null, p_status || ' (' || n || ' goals)', public.wa_email());
  return jsonb_build_object('ok', true, 'goals', n);
end $$;
comment on function public.strategy_set_approval(text) is 'wave205: an admin marks the active organizational goals approved by the board (or back to draft); logged in change_log and in each goal''s history. Until then the page shows Draft for board approval (19 Oct 2026). Access: authenticated (admins only, checked inside).';

create or replace function public.strategy_doc_save(p_id bigint, p_patch jsonb)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare v_id bigint := p_id; v_url text;
begin
  if not public.is_hub_admin() then raise exception 'Only admins add and edit the Strategy Library.'; end if;
  v_url := nullif(btrim(coalesce(p_patch->>'url', '')), '');
  if p_patch ? 'url' and v_url is not null and v_url !~ '^https://' then raise exception 'Use a full link that starts with https://'; end if;
  if v_id is null then
    if btrim(coalesce(p_patch->>'title', '')) = '' then raise exception 'A document needs a title.'; end if;
    insert into public.strategy_docs (title, url, group_label, doc_date, direction, status_note, pinned, sort, added_by)
    values (btrim(p_patch->>'title'), v_url, coalesce(nullif(btrim(p_patch->>'group_label'), ''), 'Our plans'), nullif(btrim(coalesce(p_patch->>'doc_date', '')), ''),
      nullif(btrim(coalesce(p_patch->>'direction', '')), ''), nullif(btrim(coalesce(p_patch->>'status_note', '')), ''), coalesce((p_patch->>'pinned')::boolean, true),
      (select coalesce(max(sort), 0) + 10 from public.strategy_docs), public.wa_email())
    returning id into v_id;
  else
    update public.strategy_docs set
      title = case when p_patch ? 'title' then coalesce(nullif(btrim(p_patch->>'title'), ''), title) else title end,
      url = case when p_patch ? 'url' then v_url else url end,
      group_label = case when p_patch ? 'group_label' then coalesce(nullif(btrim(p_patch->>'group_label'), ''), group_label) else group_label end,
      doc_date = case when p_patch ? 'doc_date' then nullif(btrim(p_patch->>'doc_date'), '') else doc_date end,
      direction = case when p_patch ? 'direction' then nullif(btrim(p_patch->>'direction'), '') else direction end,
      status_note = case when p_patch ? 'status_note' then nullif(btrim(p_patch->>'status_note'), '') else status_note end,
      pinned = case when p_patch ? 'pinned' then (p_patch->>'pinned')::boolean else pinned end,
      archived_at = case when p_patch ? 'archived' then case when (p_patch->>'archived')::boolean then now() else null end else archived_at end,
      updated_at = now()
    where id = v_id;
  end if;
  insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
    values ('strategy_doc', v_id::text, case when p_id is null then 'added' else 'edited' end, null, left(p_patch::text, 300), public.wa_email());
  return (select to_jsonb(d) from public.strategy_docs d where d.id = v_id);
end $$;
comment on function public.strategy_doc_save(bigint, jsonb) is 'wave205: admins add a document to the Strategy Library (p_id null) or change one (title, url, group_label, doc_date, direction, status_note, pinned, archived). Logged in change_log. Access: authenticated (admins only, checked inside).';

create or replace function public.strategy_retired_to_project(p_goal bigint)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare g record; v_pid bigint;
begin
  if not (public.is_hub_admin() or public.is_hub_leader()) then raise exception 'Leaders and admins turn a retired goal into a project.'; end if;
  select * into g from public.goals where id = p_goal for update;
  if g.id is null or g.retired_at is null or g.department = 'org' then raise exception 'Only a retired department goal becomes a project.'; end if;
  if g.moved_to_project_id is not null then raise exception 'This goal is already a project.'; end if;
  insert into public.projects (department, name, description, status, goal_id, sort, leads, created_at, updated_at)
  values (g.department, g.title, nullif(btrim(concat_ws(E'\n\n', g.detail, case when g.measure is not null then 'Measured by: ' || g.measure end)), ''), 'active',
    (select x.id from public.goals x where x.id = g.maps_to_goal_id and x.retired_at is null),
    (select coalesce(max(sort), 0) + 1 from public.projects where department = g.department), '[]'::jsonb, now(), now())
  returning id into v_pid;
  update public.goals set moved_to_project_id = v_pid where id = p_goal;
  insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
    values ('goal', p_goal::text, 'moved_to_project', g.title, 'project ' || v_pid, public.wa_email());
  return jsonb_build_object('ok', true, 'project_id', v_pid);
end $$;
comment on function public.strategy_retired_to_project(bigint) is 'wave205: the one-time "Make it a project" for a retired department goal: a new project in the same team, named after it, linked to the org goal it served (maps_to_goal_id); the goal remembers it (moved_to_project_id) and its wins and comments stay on it. Leaders and admins. Access: authenticated.';

create or replace function public.strategy_restore(p_history bigint)
returns jsonb language plpgsql security definer set search_path to '' as $$
declare h record; v_cur text; r jsonb;
begin
  select * into h from public.goal_history where id = p_history;
  if h.id is null then raise exception 'That change is not in the history.'; end if;
  perform set_config('wa205.restored_from', h.id::text, true);
  if h.entity = 'project' then
    if not public.wa205_can_comment() then raise exception 'Board viewers read the goals.'; end if;
    if h.field = 'goal_id' then
      update public.projects set goal_id = h.old_ref, milestone_id = case when h.old_ref is distinct from goal_id then null else milestone_id end, updated_at = now() where id = h.entity_id;
    elsif h.field = 'milestone_id' then
      update public.projects set milestone_id = h.old_ref, updated_at = now() where id = h.entity_id;
    end if;
    r := jsonb_build_object('ok', true);
  elsif not public.wa205_can_edit(h.goal_id) then
    raise exception 'Only this goal''s owners and the admins can restore its changes.';
  elsif h.entity = 'owner' then
    if h.field = 'added' then update public.goal_owners set removed_at = now(), is_lead = false where id = h.entity_id;
    elsif h.field = 'removed' then update public.goal_owners set removed_at = null where id = h.entity_id;
    elsif h.field = 'is_lead' then update public.goal_owners set is_lead = coalesce(h.old_value::boolean, false) where id = h.entity_id;
    elsif h.field = 'focus' then update public.goal_owners set focus = h.old_value where id = h.entity_id;
    end if;
    r := jsonb_build_object('ok', true);
  elsif h.field = 'added' then
    if h.entity = 'milestone' then update public.goal_milestones set archived_at = now(), updated_at = now(), updated_by = public.wa_email() where id = h.entity_id;
    elsif h.entity = 'path' then update public.goal_paths set archived_at = now(), updated_at = now(), updated_by = public.wa_email() where id = h.entity_id; end if;
    r := jsonb_build_object('ok', true);
  elsif h.field = 'archived_at' then
    if h.entity = 'milestone' then update public.goal_milestones set archived_at = case when h.old_value is null then null else h.old_value::timestamptz end, updated_at = now(), updated_by = public.wa_email() where id = h.entity_id;
    elsif h.entity = 'path' then update public.goal_paths set archived_at = case when h.old_value is null then null else h.old_value::timestamptz end, updated_at = now(), updated_by = public.wa_email() where id = h.entity_id; end if;
    r := jsonb_build_object('ok', true);
  elsif h.entity in ('goal', 'milestone', 'path') and h.field in ('title', 'detail', 'why', 'measure', 'baseline', 'target_fy29', 'target_fy31', 'status', 'due_date', 'body', 'fy') then
    if h.entity = 'goal' then execute format('select (%I)::text from public.goals where id = $1', h.field) into v_cur using h.entity_id;
    elsif h.entity = 'milestone' then execute format('select (%I)::text from public.goal_milestones where id = $1', h.field) into v_cur using h.entity_id;
    else select body into v_cur from public.goal_paths where id = h.entity_id; end if;
    r := public.strategy_save(h.entity, h.entity_id, h.field, coalesce(h.old_value, ''), v_cur);
  else
    raise exception 'That change cannot be restored here (%).', h.field;
  end if;
  perform set_config('wa205.restored_from', '', true);
  return r;
end $$;
comment on function public.strategy_restore(bigint) is 'wave205: Restore in a goal''s history: puts back the old value of that change (a field, a milestone or path added or removed, an owner added or removed, a project''s link). The restore is itself a change in the history (restored_from). Checks inside: the goal''s owners or an admin; project links by staff who may comment. Access: authenticated.';

-- ---------- the mention link points at the goal on the new page ----------
create or replace function public.trg_mentions_goal_comment() returns trigger
language plpgsql security definer set search_path to '' as $function$
declare g record;
begin
  if tg_op = 'UPDATE' and new.body is not distinct from old.body then return new; end if;
  select title, department into g from public.goals where id = new.goal_id;
  perform public.wa_mention_notify(new.body, case when tg_op = 'UPDATE' then old.body end, 'goal', new.goal_id, g.title,
    case when g.department = 'org' then '#orggoals/goal/' || new.goal_id || coalesce('/comments/' || new.id, '') else '#goals' end, false, 'goal_comments', new.id);
  return new;
end $function$;
comment on function public.trg_mentions_goal_comment() is 'Files @mentions written in a goal comment (wa_mention_notify, which wave138''s notify sends as a Slack DM). Since wave205 the link opens the organizational goal on Strategy > Goals (#orggoals/goal/<id>/comments/<comment>). Access: trigger only.';

-- ---------- row security ----------
alter table public.goal_owners enable row level security;
alter table public.goal_milestones enable row level security;
alter table public.goal_paths enable row level security;
alter table public.goal_history enable row level security;
alter table public.strategy_plan enable row level security;
alter table public.strategy_docs enable row level security;
create policy goal_owners_read on public.goal_owners for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
create policy goal_milestones_read on public.goal_milestones for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
create policy goal_paths_read on public.goal_paths for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
create policy goal_history_read on public.goal_history for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
create policy strategy_plan_read on public.strategy_plan for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
create policy strategy_docs_read on public.strategy_docs for select to authenticated using (public.is_wa_staff() or public.is_board_viewer());
revoke all on public.goal_owners, public.goal_milestones, public.goal_paths, public.goal_history, public.strategy_plan, public.strategy_docs from anon, authenticated;
grant select on public.goal_owners, public.goal_milestones, public.goal_paths, public.goal_history, public.strategy_plan, public.strategy_docs to authenticated;
-- the org tier: owners and admins write; retired rows only admins; new goals only admins (the department tier is retired)
create policy goals_wa205_write on public.goals as restrictive for update to authenticated
  using (public.wa205_goal_writable(id, department, retired_at)) with check (public.wa205_goal_writable(id, department, retired_at) or public.is_hub_admin());
create policy goals_wa205_insert on public.goals as restrictive for insert to authenticated with check (public.is_hub_admin());
-- comments: staff who may comment write; an author changes their own
create policy goal_comments_wa205_insert on public.goal_comments as restrictive for insert to authenticated with check (public.wa205_can_comment());
create policy goal_comments_wa205_update on public.goal_comments as restrictive for update to authenticated
  using (author_email = public.wa_email() or public.is_hub_admin() or (author_email is null and public.wa205_can_comment()))
  with check (author_email = public.wa_email() or public.is_hub_admin() or (author_email is null and public.wa205_can_comment()));

-- ---------- functions: signed-in people only, the checks inside ----------
revoke all on function public.wa205_is_owner(bigint), public.wa205_can_edit(bigint), public.wa205_can_comment(), public.wa205_goal_writable(bigint, text, timestamptz),
  public.wa205_who(), public.wa205_name(text), public.wa205_hist(),
  public.strategy_save(text, bigint, text, text, text), public.strategy_add(text, bigint, text, text), public.strategy_remove(text, bigint),
  public.strategy_owner_set(bigint, bigint, boolean, boolean, text), public.strategy_link_project(bigint, bigint, bigint),
  public.strategy_comment_add(bigint, bigint, bigint, text), public.strategy_comment_edit(bigint, text), public.strategy_set_approval(text),
  public.strategy_doc_save(bigint, jsonb), public.strategy_retired_to_project(bigint), public.strategy_restore(bigint) from public, anon;
grant execute on function public.wa205_is_owner(bigint), public.wa205_can_edit(bigint), public.wa205_can_comment(), public.wa205_goal_writable(bigint, text, timestamptz),
  public.strategy_save(text, bigint, text, text, text), public.strategy_add(text, bigint, text, text), public.strategy_remove(text, bigint),
  public.strategy_owner_set(bigint, bigint, boolean, boolean, text), public.strategy_link_project(bigint, bigint, bigint),
  public.strategy_comment_add(bigint, bigint, bigint, text), public.strategy_comment_edit(bigint, text), public.strategy_set_approval(text),
  public.strategy_doc_save(bigint, jsonb), public.strategy_retired_to_project(bigint), public.strategy_restore(bigint) to authenticated;

-- ---------- live: other people's saves arrive without a refresh (row security applies per reader) ----------
alter publication supabase_realtime add table public.goals, public.goal_milestones, public.goal_paths, public.goal_owners, public.goal_comments, public.projects;

-- ---------- goal-sync (ClickUp) is paused: the department tier it fed is retired ----------
-- goal-sync only pulls from ClickUp (it never writes there on its own and never removes anything), skips archived goals,
-- and knows every ClickUp id the Hub holds, retired rows included, so nothing comes back twice. Its daily pull would only
-- refresh retired rows' quarter (skipped) or add new department goals from the Q4 FY2026 lists. Paused, not removed:
-- select cron.alter_job(6, active := true) turns it back on.
select cron.alter_job(6, active := false);
insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
values ('cron', 'wa-goals-sync', 'active', 'true', 'false (wave205: department goals retired as a tier; goal-sync paused, nothing in ClickUp touched)', 'wave205 migration');
